package com.notificationservice.infrastructure.persistence.entity;import com.notificationservice.domain.model.ScheduledStatus;import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;
@Entity @Table(name="scheduled_notifications") public class ScheduledNotificationEntity{@Id private UUID id;@Column(name="target_role",length=32)private String targetRole;@Column(name="target_faculty",length=50)private String targetFaculty;@Column(nullable=false,length=200)private String title;@Column(nullable=false,length=2000)private String content;@Column(name="scheduled_at",nullable=false)private Instant scheduledAt;@Enumerated(EnumType.STRING)@Column(nullable=false,length=32)private ScheduledStatus status;@Column(name="created_by",nullable=false)private UUID createdBy;@Column(name="created_at",nullable=false)private Instant createdAt;@Column(name="updated_at",nullable=false)private Instant updatedAt;@Version private long version;public ScheduledNotificationEntity(){}public UUID getId(){return id;}public void setId(UUID v){id=v;}public String getTargetRole(){return targetRole;}public void setTargetRole(String v){targetRole=v;}public String getTargetFaculty(){return targetFaculty;}public void setTargetFaculty(String v){targetFaculty=v;}public String getTitle(){return title;}public void setTitle(String v){title=v;}public String getContent(){return content;}public void setContent(String v){content=v;}public Instant getScheduledAt(){return scheduledAt;}public void setScheduledAt(Instant v){scheduledAt=v;}public ScheduledStatus getStatus(){return status;}public void setStatus(ScheduledStatus v){status=v;}public UUID getCreatedBy(){return createdBy;}public void setCreatedBy(UUID v){createdBy=v;}public Instant getCreatedAt(){return createdAt;}public void setCreatedAt(Instant v){createdAt=v;}public Instant getUpdatedAt(){return updatedAt;}public void setUpdatedAt(Instant v){updatedAt=v;}public long getVersion(){return version;}public void setVersion(long v){version=v;}}
